from lib import *
recs=[
R(2265,"Kue Tulang",
"Resep kue tulang ini berasal dari resep Italia kuno bernama Ossa de Morti atau Kue Tulang Orang Mati. Kue ini disajikan pada 1 November pada Hari Orang Mati, perayaan bagi mereka yang telah meninggalkan dunia ini. Kue tulang ramah ginjal dengan hanya 22 mg fosfor per kue meskipun menggunakan almond giling.",
"12","2 kue",
["2 putih telur","1-1/4 cangkir tepung terigu putih serbaguna","1-1/4 cangkir gula pasir","1/2 cangkir gula merah","1/2 cangkir almond, digiling","1 sendok makan air lemon","1 sendok teh parutan kulit lemon","1 sendok teh kayu manis","1 sendok makan air","1/2 cangkir gula bubuk"],
["Kocok putih telur hingga terbentuk puncak kaku.","Dalam mangkuk besar, campurkan tepung, gula putih dan gula merah, almond, air lemon, parutan kulit lemon, dan kayu manis; lipat putih telur dan aduk hingga bertekstur remah. Tambahkan air dan aduk.","Bentuk adonan menjadi bola, tutup, bungkus dengan plastik pembungkus dan dinginkan selama 20 menit.","Panaskan oven terlebih dahulu hingga 350° F. Olesi loyang dengan lemak.","Bagi adonan dingin menjadi 4 bagian. Taburi tangan dengan tepung dan gulung setiap bagian menjadi tali setebal 1″ (sekitar 12″ panjangnya). Potong setiap tali menjadi bagian 2″ dan gulung hingga setebal 1/2″ dan seukuran jari.","Letakkan di atas loyang dan panggang selama 15 hingga 18 menit.","Biarkan dingin lalu gulingkan dalam gula bubuk hingga terlumuri."],
["Kue akan keras dan renyah setelah dingin","Porsi yang disarankan untuk diet diabetes adalah satu kue (16 g karbohidrat)."],
["1 makanan pokok bertepung","1 berkalori tinggi"]),
R(2266,"Pasta Ayam Pesto",
"Pesto adalah bahan yang menyatukan cita rasa dalam resep hidangan utama Pasta Ayam Pesto ini.",
"8","1 cangkir",
["10 ons pasta penne","1-1/4 pon dada ayam tanpa tulang dan tanpa kulit","1 bawang bombai kecil","1 paprika hijau besar","1 paprika merah besar","3 siung bawang putih","2 sendok makan minyak zaitun","2 sendok makan cuka balsamik","1/2 sendok teh garam (opsional)","1/4 sendok teh lada hitam","1/3 cangkir pesto basil"],
["Masak pasta sesuai petunjuk kemasan, tanpa garam. Tiriskan dan sisihkan.","Potong ayam menjadi potongan seukuran sekali suap. Potong dadu bawang bombai dan paprika. Cincang halus siung bawang putih.","Dalam wajan besar tumis bawang bombai dan paprika dalam 1 sendok makan minyak zaitun hingga lunak. Tambahkan 1 sendok makan minyak zaitun lagi, bawang putih, dan potongan ayam dan masak hingga ayam matang sekitar 5 hingga 7","menit.","Kecilkan api ke rendah dan tambahkan pasta matang, cuka balsamik, garam, dan lada. Aduk hingga tercampur rata.","Tambahkan pesto, aduk dan panaskan sebelum disajikan."],
["Gunakan pasta gandum utuh untuk meningkatkan kandungan serat.","Ganti ayam dengan kalkun atau udang untuk variasi yang lezat.","Untuk diet protein lebih rendah, kurangi ayam menjadi 12 ons (17 gram protein per porsi)."],
["2-1/2 daging","2 makanan pokok bertepung","1 sayuran, kalium sedang"]),
R(2269,"Terong Jahe Bawang Putih",
"Menjalani diet dialisis bukan berarti Anda harus makan makanan hambar. Resep ramah ginjal Terong Jahe Bawang Putih ini adalah hidangan bergaya Asia dengan banyak bahan lezat dan ramah ginjal yang ditumis bersama untuk sensasi rasa. Banyak sayuran dan rempah menjadikan hidangan pendamping ini pemenang.",
"4","3/4 cangkir",
["2 cangkir terong Cina","2 sendok teh jahe cincang halus","2 siung bawang putih","1/4 cangkir basil segar","2 sendok makan minyak wijen","1/2 cangkir potongan jamur segar","1 cangkir tauge kacang hijau","1/4 sendok teh serpihan cabai merah","1 sendok makan saus hoisin"],
["Iris terong menjadi potongan sepanjang 1-1/2 inci. Cincang halus siung bawang putih. Cincang basil.","Panaskan minyak wijen dalam wajan besar. Tambahkan terong, jahe, bawang putih, jamur, dan tauge. Tumis dengan api sedang-tinggi hingga terong mulai melunak, 4-6 menit.","Tambahkan basil, serpihan cabai, dan saus hoisin ke terong. Lanjutkan memasak selama 1-2 menit. Angkat dari api dan sajikan."],
["Jika terong Cina tidak tersedia, gunakan terong biasa. Potong menjadi dadu 1 inci (tanpa dikupas).","Saus hoisin adalah produk pasta kedelai yang tersedia di bagian makanan etnis di sebagian besar toko bahan makanan. Satu sendok makan saus hoisin mengandung 250 mg natrium (63 mg per porsi). Carilah merek Sun Luck, tersedia dari Sun Luck of Seattle, Washington. Jumlah yang sangat sedikit menambah banyak rasa!"],
["1 sayuran, kalium sedang","1-1/2 lemak"]),
R(2272,"Campuran Bumbu Herba Bawang",
"Bawang bombai dan bawang putih bubuk, paprika, peterseli, dan basil adalah 5 bahan yang membuat Campuran Bumbu Herba Bawang yang penuh rasa ini.",
"12","1 sendok makan",
["1 sendok makan bawang bombai bubuk","1 sendok makan paprika bubuk","1 sendok makan peterseli kering","2 sendok teh bawang putih bubuk","1 sendok teh basil bubuk"],
["Masukkan bahan-bahan ke dalam toples dan kocok hingga tercampur.","Simpan hingga siap digunakan untuk memasak atau masukkan ke dalam wadah penabur untuk digunakan di meja makan."],
["Gunakan wadah penabur meja dengan lubang besar."],
["tidak ada"]),
R(2273,"Nanas Panggang Kayu Manis",
"Resep Nanas Panggang Kayu Manis dari ahli gizi DaVita, Esther, lezat untuk dessert, sarapan, atau camilan.",
"6","1 potong nanas",
["1 nanas segar","2 sendok makan mentega","1/4 cangkir madu","1 sendok makan air jeruk nipis segar","1 sendok teh kayu manis","Parutan kulit jeruk nipis (opsional)"],
["Panaskan oven terlebih dahulu hingga 425° F.","Potong ujung nanas. Kupas dan buang bagian tengah, lalu potong menjadi enam potongan 1 inci.","Alasi loyang berbibir dengan foil dan semprot dengan semprotan antilengket.","Lelehkan mentega dan aduk bersama madu, air jeruk nipis, dan kayu manis dalam mangkuk kecil.","Letakkan potongan nanas dengan sisi datar menghadap ke bawah di atas loyang. Olesi setengah saus secara merata di atas potongan. Balik potongan dan ulangi dengan sisa saus.","Masukkan loyang ke dalam oven dan panggang nanas selama 10 menit. Balik potongan dan panggang 15 menit lagi hingga nanas sedikit kecokelatan dan terkaramelisasi.","Biarkan dingin sebentar, taburi dengan parutan kulit jeruk nipis dan sajikan hangat."],
["Warna luar tidak menunjukkan seberapa matang nanas. Nanas dipetik saat puncak kematangan dan tidak menjadi lebih matang setelah itu. Sebaliknya, carilah nanas dengan daun hijau penuh, kulit keras, dan aroma manis.","Gula merah dapat digunakan sebagai pengganti madu.","Nanas panggang sudah nikmat sendiri tetapi untuk dessert ramah ginjal yang lebih mewah, sajikan dengan es krim non-susu atau sesendok krim kocok buatan sendiri di atasnya."],
["1 buah, kalium sedang","1 berkalori tinggi","1 lemak"]),
R(2274,"Pai Apel",
"Ahli gizi ginjal DaVita dari Minnesota membagikan beberapa resep daerah favorit mereka yang telah dimodifikasi untuk diet dialisis. Dengan membatasi fosfor, kalium, dan natrium, pasien dialisis dapat menikmati resep Pai Apel yang lezat ini.",
"8","1/8 pai",
["6 apel sedang","1/2 cangkir gula pasir","1 sendok teh kayu manis bubuk","6 sendok makan mentega","2-2/3 cangkir tepung terigu serbaguna","1 cangkir shortening","6 sendok makan air"],
["Panaskan oven terlebih dahulu hingga 425° F.","Kupas, buang bagian tengah, dan iris apel.","Dalam mangkuk besar, campurkan irisan apel, gula, dan kayu manis. Tutup dan sisihkan.","Dalam mangkuk besar terpisah, potong shortening ke dalam tepung dengan pastry blender. Tambahkan air dingin, 1 sendok makan setiap kali dan aduk hingga adonan membentuk bola. Jika tidak, gunakan tangan untuk membentuk bola.","Bagi adonan menjadi dua dan giling satu bagian, menggunakan rolling pin dan tambahan tepung jika perlu. Letakkan dalam loyang pai 9″.","Aduk isian pai apel dan tuang ke dalam kulit pai.","Dengan potongan 1 sendok makan, letakkan mentega di sekeliling isian pai, tersebar merata.","Giling 1/2 adonan lainnya. Letakkan di atas isian pai apel, pastikan tepi pai tertutup.","Dengan pisau tajam, buat empat sayatan 1” di sekeliling bagian atas kulit pai agar udara keluar saat memanggang.","Letakkan pai di oven di atas loyang jellyroll untuk menampung cairan pai saat dipanggang.","Panggang selama 50 hingga 60 menit hingga kulit cokelat keemasan."],
["Varietas apel yang disarankan untuk pai apel yang enak meliputi: Fuji, Jonathan, Jonagold, Gala, Golden Delicious, Granny Smith, Pippin, dan Winesap. Untuk hasil terbaik cobalah menggabungkan 2 atau 3 varietas.","1 apel sedang menghasilkan 1 cangkir setelah dikupas dan dibuang bagian tengahnya."],
["1 buah, kalium rendah","2 makanan pokok bertepung","6 lemak","1/2 berkalori tinggi"]),
R(2275,"Hash Kacang Polong Mata Hitam",
"Ahli gizi ginjal Nicole dari Virginia mengucapkan semoga beruntung setiap tahun baru dengan resep Hash Kacang Polong Mata Hitam miliknya. Dengan menggabungkan kacang polong dengan nasi dan bahan lain yang lebih rendah kalium dan fosfor, Anda dapat menikmati kacang polong mata hitam pada Tahun Baru atau kapan saja.",
"6","3/4 cangkir",
["1 cangkir kacang polong mata hitam beku","2 cangkir nasi putih matang","1 sendok makan minyak zaitun","3 siung bawang putih","1 paprika merah sedang","1 bawang bombai kecil","2 batang seledri","2 wortel kecil","1/2 cangkir kale","1 lembar daun salam","3 tangkai thyme segar","1 cangkir kaldu ayam rendah natrium","1/2 sendok teh garam (opsional)","1/4 sendok teh lada hitam"],
["Biarkan kacang polong mencair. Cincang halus bawang putih; cincang bawang bombai dan paprika; iris seledri dan potong dadu wortel; buang batang kale dan cincang.","Dalam wajan besar panaskan minyak zaitun. Tambahkan bawang putih, bawang bombai, paprika, seledri, wortel, daun salam, dan thyme. Tumis dengan api sedang-kecil hingga harum, sekitar 5 menit.","Tambahkan kale, kacang polong mata hitam, garam, dan lada hitam. Aduk perlahan bersama.","Tambahkan kaldu ayam dan didihkan perlahan sekitar 15 menit atau hingga kaldu habis.","Panaskan nasi; sendokkan hash di atas nasi, hiasi dengan tangkai thyme atau peterseli segar dan sajikan."],
["Anda juga dapat mendidihkan semua bahan bersama dengan nasi dan menyajikannya tercampur jika diinginkan.","Tambahkan saus cabai pedas jika diinginkan. Pilih merek rendah natrium.","Jika tersedia, ganti kacang polong beku dengan kacang polong segar matang rendah natrium."],
["1-1/2 makanan pokok bertepung","1 sayuran, kalium sedang"]),
R(2277,"Pai Freezer Margarita",
"Seiris Pai Freezer Margarita buatan Grace menghadirkan rasa jeruk nipis manis yang pasti menjadikannya pai favorit baru Anda. Selain rasanya yang enak, pai 5 bahan ini sangat mudah dibuat. Ikuti resep ramah ginjal ini untuk salah satu pai freezer terbaik yang pernah Anda coba.",
"10","1/10 potong pai",
["5 cangkir es krim vanilla bean rendah lemak","6 ons konsentrat limeade beku","2 jeruk nipis segar","1 sampai 2 tetes pewarna makanan hijau (opsional)","1 kulit graham cracker"],
["Keluarkan es krim agar melunak; cairkan konsentrat limeade. Parut kulit satu jeruk nipis dan ukur 2 sendok teh untuk ditambahkan ke campuran pai. Peras jeruk nipis yang sudah diparut kulitnya dan ukur 1 sendok makan.","Campurkan es krim yang telah lunak, limeade, air jeruk nipis, dan parutan kulit jeruk nipis dalam mangkuk besar. Aduk hingga tercampur rata.","Tuang campuran ke dalam kulit graham cracker. Tutup dan bekukan hingga keras.","Potong pai menjadi 10 porsi. Hiasi setiap iris dengan irisan jeruk nipis segar."],
["Untuk variasi ganti konsentrat jeruk nipis dengan konsentrat beku cranberry, lemon, atau nanas.","Dessert ini tidak disarankan untuk penderita diabetes karena kandungan karbohidrat yang tinggi. Namun Anda dapat melakukan perubahan berikut untuk mengurangi karbohidrat menjadi 26 gram per porsi: buat isian dan bekukan dalam cangkir dessert dan bagi menjadi 10 porsi; hilangkan kulit graham cracker; dan gunakan es krim bebas gula."],
["1 makanan pokok bertepung","1 susu","1 berkalori tinggi"]),
R(2281,"Pai Stroberi",
"Ada sesuatu yang menenangkan dari resep ramah ginjal Pai Stroberi. Cobalah hari ini.",
"8","1/8 pai",
["1 kulit pai belum dipanggang, ukuran 9”","4 cangkir stroberi, segar atau beku","1 cangkir gula","3 sendok makan tepung maizena","2 sendok makan air lemon","8 sendok makan topping kocok (opsional)"],
["Panggang kulit pai sesuai petunjuk pada kemasan. Sisihkan hingga dingin.","Haluskan 2 cangkir stroberi dan campurkan dengan gula, tepung maizena, dan air lemon.","Masukkan bahan-bahan ke dalam panci sedang. Masak dengan api sedang, aduk hingga campuran kental dan bening. Biarkan dingin.","Iris sisa stroberi dan tambahkan ke campuran yang telah dingin.","Tuang ke dalam kulit pai yang telah dingin. Tutup dan simpan di lemari es hingga dingin.","Sajikan dengan topping kocok jika diinginkan."],
["Karena kandungan karbohidrat yang tinggi, porsi setengah disarankan jika Anda menderita diabetes. Pengganti gula dapat digunakan untuk menggantikan gula dalam banyak resep. Konsultasikan dengan ahli gizi Anda untuk penyesuaian resep atau ukuran porsi berdasarkan kebutuhan karbohidrat individu Anda.","Jika pengganti gula digunakan sebagai pengganti gula, karbohidrat berkurang menjadi 20 gram, pilihan karbohidrat berkurang menjadi satu."],
["1 makanan pokok bertepung","1 buah, kalium sedang","1 berkalori tinggi","1 lemak"]),
R(2282,"Custard French Toast Panggang",
"Custard French Toast Panggang dari ahli gizi DaVita, Susan, adalah favorit di pusat dialisis DaVita miliknya dan pasti akan menyenangkan seluruh keluarga.",
"4","1 iris roti",
["4 iris roti Italia, diiris setebal 1/2”","4 cangkir susu beras, tanpa fortifikasi","2 cangkir pengganti telur cair rendah kolesterol","1/2 cangkir gula","4 sendok makan margarin tanpa garam, dilelehkan","1 sendok teh ekstrak almond","1 sendok teh kayu manis","Gula bubuk atau pemanis tanpa kalori, opsional"],
["Olesi dasar dan sisi loyang 9” x 13” dengan margarin atau semprotan masak antilengket.","Tata irisan roti dalam satu lapisan di dasar loyang.","Kocok susu beras tanpa fortifikasi, pengganti telur, margarin leleh, gula, ekstrak almond, dan kayu manis bersama dalam mangkuk dan tuang di atas irisan roti.","Tutup loyang dengan plastik pembungkus dan simpan di lemari es semalaman.","Panaskan oven terlebih dahulu hingga 350° F.","Masukkan loyang ke dalam oven dan panggang selama 40 hingga 50 menit, hingga pisau yang ditusukkan ke tengah keluar bersih.","Sajikan hangat.","Taburi dengan gula bubuk atau pemanis tanpa kalori, jika diinginkan."],
["Creamer non-susu polos atau berperisa dapat digunakan sebagai pengganti susu beras. Susan mengatakan pasien dan rekan timnya lebih menyukai rasa krim kelapa.","Ekstrak vanila atau kelapa dapat digunakan sebagai pengganti ekstrak almond.","Untuk penderita diabetes gunakan pemanis granular Splenda® sebagai pengganti gula untuk mengurangi karbohidrat menjadi 44 gram dan kalori menjadi 364 per porsi atau sajikan setengah porsi.","Pengganti telur cair disarankan. Jika telur digunakan sebagai gantinya, kalori 550, lemak 24 g, fosfor 263 mg dan kolesterol 423 mg."],
["2 daging","2 makanan pokok bertepung","1 lemak","2-1/2 berkalori tinggi"]),
R(2283,"Vinaigrette Kunyit",
"Dressing sederhana ini menghadirkan perpaduan rasa untuk salad dan sebagai dip untuk sayuran.",
"4","2 sendok makan",
["1/4 cangkir, ditambah 2 sendok makan minyak zaitun extra virgin","4 siung bawang putih","3 sendok makan air lemon","2 sendok teh madu","2 sendok teh kunyit","1/2 sendok teh mustard Dijon","1/8 sendok teh lada hitam"],
["Potong-potong bawang putih. Masukkan semua bahan ke dalam blender atau food processor dan blender hingga halus.","Simpan sisa di lemari es dalam wadah kedap udara."],
["Kunyit dikatakan mengandung sifat antiinflamasi.","Anda juga dapat menggunakan hand blender untuk mencampur bahan.","Untuk menghemat waktu, cincang halus bawang putih terlebih dahulu, masukkan bahan-bahan dan kocok dengan baik dalam wadah."],
["3 lemak"]),
R(2288,"Ikan Goreng dengan Nasi Berbumbu",
"Ikan Goreng dengan Nasi Berbumbu adalah hidangan satu piring ramah ginjal yang penuh rasa dari lada hitam, jintan, dan campuran bumbu herba.",
"4","3-1/2 ons ikan dengan 1/2 cangkir nasi",
["1 bawang bombai besar","1 cangkir minyak sayur","1 cangkir beras putih, mentah","1/2 sendok teh garam","2 cangkir air","1 pon fillet ikan kod beku","1 cangkir tepung terigu putih serbaguna","1-1/2 sendok teh jintan bubuk","1-1/2 sendok teh lada hitam","1 sendok teh campuran bumbu herba tanpa garam"],
["Cairkan ikan. Potong dadu bawang bombai.","Dalam panci berukuran sedang tambahkan 2 sendok teh minyak dan tumis bawang bombai.","Setelah bawang bombai kecokelatan, tetapi tidak gosong, tambahkan beras, 2 cangkir air, 1/2 sendok teh jintan, dan 1/2 sendok teh lada hitam.","Masak tertutup sekitar 20 menit dengan api sedang-kecil.","Dalam mangkuk, tambahkan tepung, 1 sendok teh jintan, 1 sendok teh lada hitam, dan bumbu tanpa garam dan aduk rata.","Panaskan sisa minyak dalam wajan atau penggorengan. Keringkan ikan yang telah dicairkan dengan tisu dapur untuk menghilangkan semua kelebihan air. Celupkan ikan dalam campuran tepung dan goreng dalam minyak panas.","Sajikan ikan panas dengan nasi berbumbu."],
["Pilih ikan putih apa pun untuk resep ini.","Jintan adalah rempah yang dikenal membantu pencernaan tetapi bisa terasa kuat jika seseorang tidak terbiasa mengonsumsinya. Sesuaikan jumlah dengan selera Anda","Jika diinginkan, pelengkap untuk Ikan Goreng dengan Nasi Berbumbu meliputi: bawang bombai putih yang direndam cuka dengan lada hitam atau saus tahini (2 sendok makan tahini dengan 1–2 sendok teh cuka putih, lada hitam, dan jintan).","Untuk diet protein lebih rendah bagi ikan menjadi 6 porsi, bukan 4; protein berkurang menjadi 17 gram untuk makanan tersebut."],
["3 daging","3-1/2 makanan pokok bertepung","1/2 sayuran, kalium sedang","1 lemak"]),
R(2289,"Semur Jelai dan Daging Sapi",
"Semur Jelai dan Daging Sapi adalah cara hangat dan lezat untuk mendapatkan protein dalam diet dialisis. Anda dapat menikmati hidangan mengenyangkan ini untuk makan siang atau makan malam.",
"6","1-1/4 cangkir",
["1 cangkir jelai mutiara, mentah","1 pon daging sapi semur tanpa lemak","2 sendok makan tepung terigu putih serbaguna","1/4 sendok teh lada hitam","1/2 sendok teh garam","2 sendok makan minyak canola","1/2 cangkir bawang bombai","1 batang seledri besar","1 siung bawang putih","2 wortel sedang","2 lembar daun salam","1 sendok teh bumbu herba bawang Mrs. Dash®"],
["Rendam jelai dalam 2 cangkir air selama 1 jam.","Potong dadu bawang bombai dan seledri. Cincang halus siung bawang putih. Iris wortel setebal 1/4 inci. Potong daging sapi menjadi dadu 1-1/2 inci.","Masukkan tepung, lada hitam, dan daging semur ke dalam kantong plastik. Kocok untuk melumuri daging semur dengan tepung.","Panaskan minyak dalam panci tebal 4 quart dan cokelatkan daging semur. Angkat daging dari panci.","Tumis dan aduk bawang bombai, seledri, dan bawang putih dalam minyak sisa daging selama 2 menit. Tambahkan 2 quart air dan didihkan. Masukkan kembali daging ke dalam panci. Tambahkan daun salam dan garam. Kecilkan api hingga mendidih perlahan.","Tiriskan dan bilas jelai, lalu tambahkan ke dalam panci. Tutup dan masak selama 1 jam. Aduk setiap 15 menit.","Setelah 1 jam tambahkan wortel iris dan bumbu herba Mrs. Dash®. Didihkan perlahan selama satu jam lagi. Tambahkan air jika perlu untuk mencegah lengket."],
["Untuk diet protein lebih rendah PGK non-dialisis, kurangi daging sapi menjadi 8 ons per resep. Protein akan berkurang menjadi 14 gram per porsi."],
["3 daging","1 sayuran kalium sedang","1 makanan pokok bertepung"]),
R(2290,"Dip Apel Gula Merah",
"Buat dip cepat untuk apel varietas favorit Anda. Hanya dengan 3 bahan, Dip Apel Gula Merah cepat, mudah, dan ramah ginjal.",
"8","2 sendok makan",
["8 ons krim keju","3/4 cangkir gula merah, tidak dipadatkan","1/2 sendok teh ekstrak vanila"],
["Keluarkan krim keju selama 20 menit pada suhu ruang agar melunak.","Dengan mixer tangan, campurkan krim keju, gula merah, dan vanila hingga benar-benar tercampur.","Nikmati dip dengan irisan apel."],
["Dip ini enak dengan apel Red Delicious atau Granny Smith."],
["1/2 susu","1/2 berkalori tinggi"]),
R(2291,"Ayam Lemon Thyme",
"Resep ramah ginjal Ayam Lemon Thyme ini empuk, juicy, penuh rasa, dan cukup istimewa untuk tamu.",
"4","1 dada ayam",
["1 pon dada ayam tanpa tulang dan tanpa kulit","2 sendok makan minyak canola","1 cangkir bawang bombai, potong dadu","14 ons kaldu ayam rendah natrium","1/2 cangkir air lemon","1 sendok makan thyme segar, dicincang","1/4 sendok teh lada hitam"],
["Rapikan dada ayam dan pukul hingga tipis.","Dalam wajan besar, cokelatkan ayam dalam minyak.","Pindahkan ayam ke piring, dan sisihkan.","Tambahkan bawang bombai ke minyak yang tersisa di wajan dan tumis hingga bawang bombai transparan.","Tambahkan kaldu, air lemon, thyme, dan lada hitam. Lanjutkan memasak selama 10 menit.","Kembalikan ayam ke wajan dan masak 10 menit lagi, sesekali diaduk.","Sajikan panas."],
["Belilah dada ayam iris tipis di konter daging untuk menghindari pemukulan, jika diinginkan.","Ide penyajian: di atas nasi dengan buncis, atau dengan mi dan wortel atau sebagai sandwich terbuka di atas roti putih dan siram dengan campuran kaldu.","Kaldu rendah natrium mengandung 140 mg atau kurang natrium per porsi. Kaldu natrium berkurang mengandung 220 hingga 600 mg natrium per porsi.","Hindari kaldu rendah natrium dengan kalium klorida — sangat tinggi kalium.","Jika Anda menjalani diet rendah protein sesuaikan porsi dengan rencana makan Anda."],
["4 daging","1/2 sayuran, kalium rendah"]),
]
save(6,recs)
